/* =========================================================================
   bundle.js — inline every stylesheet and script into one HTML file.

   The folder build is the reference; this is the one you can hand to somebody.
   A single file cannot be separated from its dependencies by a download, an
   email attachment, a Slack upload or a drag onto the desktop, all of which
   silently break a relative-path folder and produce a blank page with nothing
   in the console to explain it.

   Run:  node tools/bundle.js
   ========================================================================= */

const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const read = (p) => fs.readFileSync(path.join(root, p), 'utf8');

const CSS = ['css/tokens.css', 'css/app.css', 'css/spec.css'];
const JS = ['js/dom.js', 'js/data.js', 'js/components.js', 'js/registry.js',
            'js/screens.js', 'js/screens-mobile.js', 'js/app.js'];

/* A literal </script> anywhere in the source would close the tag early. None
   is present today, but a bundler that breaks silently later is worse than one
   that refuses now. */
function guard(src, file) {
  if (/<\/script/i.test(src)) {
    throw new Error(`${file} contains a literal </script>, which cannot be inlined as-is`);
  }
  return src;
}

let html = read('index.html');

const styles = CSS.map((f) => `/* ===== ${f} ===== */\n${read(f)}`).join('\n\n');
const scripts = JS.map((f) => `/* ===== ${f} ===== */\n${guard(read(f), f)}`).join('\n\n');

// Replace the three <link rel=stylesheet> to local files with one <style>.
html = html.replace(
  /<link rel="stylesheet" href="css\/tokens\.css">[\s\S]*?<link rel="stylesheet" href="css\/spec\.css">/,
  `<style>\n${styles}\n</style>`
);

// Replace the seven <script src> with one <script>.
html = html.replace(
  /<script src="js\/dom\.js"><\/script>[\s\S]*?<script src="js\/app\.js"><\/script>/,
  `<script>\n${scripts}\n</script>`
);

html = html.replace(
  '<title>MatchRead — Visual Product Specification — US Open 2026</title>',
  '<title>MatchRead — Visual Product Specification — US Open 2026</title>\n<!-- Single-file build. Generated by tools/bundle.js from the folder in this\n     same directory; edit there and rebuild, never edit this file. -->'
);

const out = path.join(root, 'matchread-spec.html');
fs.writeFileSync(out, html);

/* Verify the inlining actually happened rather than silently no-op'ing on a
   regex that stopped matching. */
const problems = [];
if (/<link rel="stylesheet" href="css\//.test(html)) problems.push('a local stylesheet link survived');
if (/<script src="js\//.test(html)) problems.push('a local script tag survived');
for (const f of CSS.concat(JS)) {
  if (!html.includes(`/* ===== ${f} ===== */`)) problems.push(`${f} was not inlined`);
}
if (problems.length) {
  console.error('BUNDLE FAILED:\n  ' + problems.join('\n  '));
  process.exit(1);
}

console.log(`wrote matchread-spec.html — ${(html.length / 1024).toFixed(0)} KB, ${CSS.length} stylesheets + ${JS.length} scripts inlined`);
